#include <unordered_map>
#include <list>
#include <utility>

class LRUCache {
private:
    int capacity;
    std::list<std::pair<int, int>> cacheList; // front = most recently used, back = least recently used
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> cacheMap;

public:
    LRUCache(int capacity) : capacity(capacity) {}

    int get(int key) {
        auto it = cacheMap.find(key);
        if (it == cacheMap.end()) {
            return -1;
        }
        // Move the accessed element to the front (most recently used)
        cacheList.splice(cacheList.begin(), cacheList, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = cacheMap.find(key);
        if (it != cacheMap.end()) {
            // Key exists: update value and move to front
            it->second->second = value;
            cacheList.splice(cacheList.begin(), cacheList, it->second);
        } else {
            // Key does not exist
            if (static_cast<int>(cacheMap.size()) == capacity) {
                // Evict the least recently used item (back of the list)
                auto lru = cacheList.back();
                cacheMap.erase(lru.first);
                cacheList.pop_back();
            }
            // Insert new item at the front
            cacheList.push_front({key, value});
            cacheMap[key] = cacheList.begin();
        }
    }
};
